-- Use stored roles; auth_user_roles intentionally aliases Safety/Claims to Accounting.
alter policy "Statement readers" on public.trip_week_statements using ((select exists (select 1 from public.user_roles where user_id = auth.uid() and role in ('admin'::public.app_role,'accounting'::public.app_role,'manager'::public.app_role))));
alter policy "Statement uploads" on public.trip_week_statements with check ((select exists (select 1 from public.user_roles where user_id = auth.uid() and role in ('admin'::public.app_role,'accounting'::public.app_role))));
alter policy "Statement replacements" on public.trip_week_statements using ((select exists (select 1 from public.user_roles where user_id = auth.uid() and role in ('admin'::public.app_role,'accounting'::public.app_role)))) with check ((select exists (select 1 from public.user_roles where user_id = auth.uid() and role in ('admin'::public.app_role,'accounting'::public.app_role))));
alter policy "Read trip statements" on storage.objects using (bucket_id = 'trip-statements' and (select exists (select 1 from public.user_roles where user_id = auth.uid() and role in ('admin'::public.app_role,'accounting'::public.app_role,'manager'::public.app_role))));
alter policy "Upload trip statements" on storage.objects with check (bucket_id = 'trip-statements' and (select exists (select 1 from public.user_roles where user_id = auth.uid() and role in ('admin'::public.app_role,'accounting'::public.app_role))));
alter policy "Delete replaced trip statements" on storage.objects using (bucket_id = 'trip-statements' and (select exists (select 1 from public.user_roles where user_id = auth.uid() and role in ('admin'::public.app_role,'accounting'::public.app_role))));
